"""Gera a prévia pública dos portais usando capturas do teste real, sem avaliações no cliente."""
import base64
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
source=ROOT/'docs/demonstracao'
config={
 'aluno':[
  ('1 · Denúncia','01-denuncia.png'),('2 · Recebimento e hashes','02-preservacao.png'),
  ('3 · Pedidos por plataforma','03-pedidos.png'),('4 · Análise dos provedores','04-respostas.png'),
  ('4 · Perícia e arrecadação','11-pericia.png'),('5 · Atualização','05-atualizacao.png'),
  ('6 · Relatório','06-relatorio.png')],
 'professor':[
  ('Acompanhamento e senhas','07-instrutor.png'),('Pedidos nominais por plataforma','09-pedidos-professor.png'),
  ('Análises por identificador','10-analises-professor.png'),('Avaliação da perícia','12-pericia-professor.png')]
}
data={role:[dict(title=title,image='data:image/png;base64,'+base64.b64encode((source/name).read_bytes()).decode()) for title,name in entries] for role,entries in config.items()}
css=(ROOT/'static/style.css').read_text()
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operação LUA · Prévia dos portais</title><style>'''+css+'''.preview{width:100%;height:auto;border:1px solid #334a64;border-radius:10px}.role-buttons{display:flex;gap:12px;flex-wrap:wrap}.preview-note{border-left:3px solid #e0b571}#screenButtons{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}#screenButtons button{background:#263d55;color:#dce9f7}#screenButtons button[aria-pressed=true]{background:#78d6c1;color:#0e2926}</style><body><header><div class="brand-icon">☾</div><div><span class="eyebrow">PRÉVIA DAS TELAS · TESTE REAL EXECUTADO</span><h1>Operação LUA</h1></div><span class="badge">ALUNO E PROFESSOR</span></header><main><section class="preview-note"><h2>Portais separados, avaliações pelo professor</h2><p>Esta página apresenta capturas da aplicação real, testada com duas equipes. Escolha o portal e uma tela para avaliar o resultado. Os botões dentro das capturas não são interativos.</p><p>O recebimento de respostas nominais, a avaliação e o envio de senhas funcionam no serviço com autenticação. Esta prévia do GitHub Pages não recebe respostas nem permite autoaprovação.</p><p><strong>Imagens iniciais:</strong> ZIP com 11 imagens e seus hashes. <strong>Perícia posterior:</strong> polícia no local e caderno (A21 e A22), em ZIP separado, somente após pedido aprovado e liberação do professor.</p></section><div class="role-buttons"><button id="student" aria-pressed="true">Ver portal do aluno</button><button id="teacher" class="secondary" aria-pressed="false">Ver portal do professor</button></div><div id="screenButtons" aria-label="Telas por fase"></div><h2 id="screenTitle"></h2><img id="screen" class="preview" alt=""><footer>Prévia visual · 13 testes de integração e percurso real das seis fases · As respostas demonstrativas não são gabarito.</footer></main><script>const DATA='''+json.dumps(data,ensure_ascii=False)+''';let role='aluno',position=0;function render(){const entries=DATA[role];document.querySelector('#screenButtons').replaceChildren();entries.forEach((entry,i)=>{const b=document.createElement('button');b.textContent=entry.title;b.setAttribute('aria-pressed',i===position?'true':'false');b.onclick=()=>{position=i;render();};document.querySelector('#screenButtons').append(b);});document.querySelector('#screenTitle').textContent=entries[position].title;const img=document.querySelector('#screen');img.src=entries[position].image;img.alt='Captura real: '+entries[position].title;document.querySelector('#student').setAttribute('aria-pressed',role==='aluno');document.querySelector('#teacher').setAttribute('aria-pressed',role==='professor');}document.querySelector('#student').onclick=()=>{role='aluno';position=0;render();};document.querySelector('#teacher').onclick=()=>{role='professor';position=0;render();};render();</script></body></html>'''
for relative in ['index.html','docs/index.html','distribuicao/Operacao_LUA_Teste_Navegador.html']:(ROOT/relative).write_text(html)
print('Prévia visual atualizada: aluno, professor e telas individualizadas; nenhum controle de autoaprovação.')
